using System;using System.IO;using System.Linq;using System.Drawing;using System.Threading.Tasks;using System.Windows.Forms;using System.Web.Script.Serialization;
namespace CFEditor {
sealed partial class EditorForm {
 internal async Task<object> CheckSystemUI(string folder){WaitPreviewIdle();await RefreshDevice();await ChangePage(2);
  var tuner=AllChildren(pages[2]).OfType<TunerDisplay>().Single();
  tuner.SetActive(false);tuner.SetNote(0);tuner.SetCents(0);TestNeed(tuner.NoteText=="—"&&tuner.ReadingText=="Afinador desactivado"&&!tuner.Reading,"Inactive tuner displays an old note");
  tuner.SetActive(true);TestNeed(!tuner.Reading,"Enabled tuner reused a stale measurement");tuner.SetNote(0);tuner.SetCents(-1);TestNeed(tuner.NoteText=="E"&&tuner.ReadingText=="-1 cent","Native note/cents mapping");
  foreach(int cents in new[]{-50,-15,0,1,15,50}){tuner.SetCents(cents);TestNeed(tuner.Reading,"Valid native pitch rejected");}
  tuner.SetCents(51);TestNeed(!tuner.Reading,"Invalid pitch displayed as a valid measurement");tuner.SetCents(0);tuner.SetNote(12);TestNeed(tuner.NoteText=="—"&&!tuner.Reading,"Invalid note displayed");
  tuner.SetNote(0);var tuneCard=tuner.Parent.Parent;var tempoHeading=AllChildren(pages[2]).OfType<Label>().Single(c=>c.Text=="TEMPO");TestNeed(tempoHeading.Parent.Top>=tuneCard.Bottom,"Tempo is not below tuner");
  var credit=AllChildren(this).OfType<LinkLabel>().Single(c=>c.Text=="Desarrollado por conr4d");var origin=PointToClient(credit.PointToScreen(Point.Empty));TestNeed(Math.Abs(origin.X+credit.Width/2.0-ClientSize.Width/2.0)<8,"Footer credit is not centered");
  Snapshot(Path.Combine(folder,"system-tuner.png"),2);
  foreach(int cents in new[]{-10,10}){tuner.SetCents(cents);TestNeed(tuner.NoteColor==Color.White&&tuner.IndicatorColor==(cents<0?UITheme.Error:UITheme.Success),"Tuner colors differ from requested sign colors");using(var bitmap=new Bitmap(tuner.Width,tuner.Height)){tuner.DrawToBitmap(bitmap,tuner.ClientRectangle);int white=0,colored=0;for(int x=0;x<bitmap.Width;x++)for(int y=0;y<bitmap.Height;y++){int pixel=bitmap.GetPixel(x,y).ToArgb();if(pixel==Color.White.ToArgb())white++;if(pixel==tuner.IndicatorColor.ToArgb())colored++;}TestNeed(white>25&&colored>50,"Tuner white note or bold pitch indication was not painted");bitmap.Save(Path.Combine(folder,cents<0?"tuner-minus.png":"tuner-plus.png"));}}tuner.SetCents(0);
  using(var testLog=new DarkLogBox{Size=new Size(400,150),Font=FirmwareText.Log}){pages[2].Controls.Add(testLog);testLog.BringToFront();testLog.CreateControl();testLog.AppendText(string.Join(Environment.NewLine,Enumerable.Range(0,120).Select(i=>"Activity "+i)));Application.DoEvents();TestNeed(testLog.LastScrollLine>50,"Log does not expose scroll range");testLog.ScrollToLine(0);TestNeed(testLog.FirstLine==0,"Log cannot scroll to start");testLog.Wheel(-120);TestNeed(testLog.FirstLine>0,"Log wheel did not scroll");testLog.ScrollToLine(testLog.LastScrollLine);TestNeed(testLog.FirstLine>50,"Log cannot scroll to end");pages[2].Controls.Remove(testLog);}
  string userName="Mi preset personal";presetName.Text=userName;int pendingBefore=pending.Count;string[] assetIds=selectors.Values.Select(c=>((Asset)c.SelectedItem).id).ToArray();
  AppLanguage.Set(true,false);TestNeed(nav[0].Text=="SOUND"&&nav[2].Text=="SYSTEM"&&nav[5].Text=="CHANGE NAM / IR"&&credit.Text=="Developed by conr4d","Language switch did not translate captions");TestNeed(presetName.Text==userName&&pending.Count==pendingBefore&&assetIds.SequenceEqual(selectors.Values.Select(c=>((Asset)c.SelectedItem).id)),"Language switch changed user or device data");
  foreach(int page in new[]{0,1,2,3,4,5}){await ChangePage(page);Application.DoEvents();Snapshot(Path.Combine(folder,"english-"+page+".png"),page);}
  var view=firmware.DataView;view.SelectSlot(0);TestNeed(AllChildren(view).OfType<ActionButton>().Any(c=>c.Text=="1. Load IR…"),"Dynamic IR caption not translated");view.SelectSlot(3);TestNeed(AllChildren(view).OfType<ActionButton>().Any(c=>c.Text=="1. Load NAM…"),"Dynamic NAM caption not translated");
  await ChangePage(4);AppLanguage.Set(false,false);TestNeed(AllChildren(view).OfType<ActionButton>().Any(c=>c.Visible&&c.Text=="Instalar Custom Firmware"),"Initial action did not return to Spanish");await ChangePage(5);TestNeed(nav[0].Text=="SONIDO"&&credit.Text=="Desarrollado por conr4d"&&AllChildren(view).OfType<ActionButton>().Any(c=>c.Text=="1. Cargar NAM…"),"Spanish captions not restored");Snapshot(Path.Combine(folder,"dark-log.png"),5);
  TestNeed(!AppDomain.CurrentDomain.GetAssemblies().Any(a=>a.GetName().Name=="EngineCLIWrapper"),"System UI test loaded SDK");return new{passed=true,hardware_accessed=false,USB_opened=false,tuner_white_note_red_negative_green_positive=true,tuner_native_note_mapping=true,stale_and_invalid_readings_hidden=true,tempo_below_tuner=true,footer_credit_centered=true,dark_log_scroll_tested=true,spanish_english_switch_tested=true,language_did_not_change_device_data=true};
 }
}
static class SystemUIChecks {public static int Run(string folder){folder=Path.GetFullPath(folder);Directory.CreateDirectory(folder);int result=1;using(var form=new EditorForm(true,false,false,false)){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-12000,-12000);form.ShowInTaskbar=false;form.Shown+=async delegate{try{File.WriteAllText(Path.Combine(folder,"result.json"),new JavaScriptSerializer().Serialize(await form.CheckSystemUI(folder)));result=0;}catch(Exception error){File.WriteAllText(Path.Combine(folder,"result.json"),new JavaScriptSerializer().Serialize(new{passed=false,USB_opened=false,error=error.ToString()}));}finally{form.Close();}};Application.Run(form);}return result;}}
}
#endif
